export async function main({ fesTerm, params }) {
  const terminal = params.terminal;
  const before = await fesTerm.readScreen({ target: terminal, maxBytes: 4096 });
  await fesTerm.sendText({ target: terminal, text: "echo " + params.greeting });
  await fesTerm.sendKeys({ target: terminal, keys: ["Enter"] });
  const change = await fesTerm.waitForChange({
    target: terminal,
    afterRevision: before.revision,
    timeoutMs: 5000,
  });
  const after = await fesTerm.readScreen({ target: terminal, maxBytes: 4096 });
  return change.changed && after.text.includes(params.greeting);
}
